    ToolCallErrorClassV1: {
      description:
        'Why a terminal call ended the way it did, in the terms the session shows.\n\nIt is the stored error\'s own category — never a reading of the message text — so the\nrow, the group header and the chip can name the same reason the Store recorded, and a\n`not_found` never reads as a permission problem. `Other` is the honest answer for a\ncategory this vocabulary does not distinguish; a legacy row with no error carries\n`None` instead, which is a different fact from "something else went wrong".',
      oneOf: [
        { const: 'not_found', description: 'The named object does not exist.', type: 'string' },
        {
          const: 'permission',
          description: 'The call was refused by policy, scope or credentials.',
          type: 'string',
        },
        {
          const: 'conflict',
          description: 'The state the call assumed had changed.',
          type: 'string',
        },
        {
          const: 'invalid_request',
          description: 'The request itself was unusable: arguments, envelope or schema.',
          type: 'string',
        },
        {
          const: 'unavailable',
          description: 'The capability, backend or dependency was not available.',
          type: 'string',
        },
        {
          const: 'other',
          description: 'A category this vocabulary does not further distinguish.',
          type: 'string',
        },
      ],
    },
