        consent: { anyOf: [{ $ref: '#/$defs/NativeSessionConsentRef' }, { type: 'null' }] },
        desktop_app_consent: {
          anyOf: [{ $ref: '#/$defs/DesktopAppConsentRef' }, { type: 'null' }],
          description: 'A program the user authorized for one session.',
        },
        file_consent: {
          anyOf: [{ $ref: '#/$defs/FileSessionConsentRef' }, { type: 'null' }],
          description:
            'The reusable file consent, present only when an ordinary file approval recorded one.',
        },
        lifetime: { $ref: '#/$defs/AuthorizationLifetime' },
        mcp_consent: {
          anyOf: [{ $ref: '#/$defs/McpTurnConsentRef' }, { type: 'null' }],
          description: 'A ReadOnly answer covering one MCP server for the rest of the turn.',
        },
        memory_consent: { anyOf: [{ $ref: '#/$defs/MemorySessionConsentRef' }, { type: 'null' }] },
        network_consent: {
          anyOf: [{ $ref: '#/$defs/NetworkSessionConsentRef' }, { type: 'null' }],
        },
        operation_fingerprint: { $ref: '#/$defs/CanonicalSha256HashV1' },
        profile: { $ref: '#/$defs/SecurityProfile' },
